1	#!/usr/bin/env node
2	// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
3	//        todo done <id>
4	//        todo list [--tag TAG]
5	//        todo search <query>
6	//        todo tag <id> <tag> | untag <id> <tag>
7	//        todo recur <id> <daily|weekly|monthly|none>
8	//        todo export --json | --csv
9	// The list is stored in $TODO_FILE (default: ./todo.json).
10	import { existsSync } from "node:fs";
11	import { TodoList } from "../src/todo.js";
12	
13	const file = process.env.TODO_FILE ?? "todo.json";
14	const [cmd, ...args] = process.argv.slice(2);
15	
16	function fail(msg) {
17	  console.error(msg);
18	  process.exit(1);
19	}
20	
21	function printItems(items) {
22	  for (const i of items) {
23	    const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
24	    const tags = i.tags?.length ? ` #${i.tags.join(" #")}` : "";
25	    const repeat = i.repeat ? ` (${i.repeat})` : "";
26	    console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}${repeat}${tags}`);
27	  }
28	}
29	
30	function csvField(v) {
31	  const s = v === null || v === undefined ? "" : Array.isArray(v) ? v.join(";")
32	    : typeof v === "object" ? JSON.stringify(v) : String(v);
33	  return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
34	}
35	
36	function toCsv(items) {
37	  const cols = ["id", "title", "done", "due", "priority", "tags", "repeat"];
38	  return [cols.join(","), ...items.map(i => cols.map(c => csvField(i[c])).join(","))].join("\n");
39	}
40	
41	const list = existsSync(file) ? TodoList.load(file) : new TodoList();
42	
43	try {
44	  if (cmd === "add") {
45	    const opts = {};
46	    const words = [];
47	    for (let i = 0; i < args.length; i++) {
48	      if (args[i] === "--due") opts.due = args[++i];
49	      else if (args[i] === "--priority") opts.priority = args[++i];
50	      else words.push(args[i]);
51	    }
52	    const item = list.add(words.join(" "), opts);
53	    list.save(file);
54	    console.log(`added ${item.id}: ${item.title}`);
55	  } else if (cmd === "done") {
56	    const { item, next } = list.completeAndReschedule(Number(args[0]));
57	    list.save(file);
58	    console.log(`completed ${item.id}: ${item.title}`);
59	    if (next) console.log(`next ${next.id}: due ${next.due.slice(0, 10)}`);
60	  } else if (cmd === "list") {
61	    let items = list.sorted();
62	    const t = args.indexOf("--tag");
63	    if (t !== -1) {
64	      if (!args[t + 1]) fail("--tag requires a value");
65	      const tagged = new Set(list.byTag(args[t + 1]));
66	      items = items.filter(i => tagged.has(i));
67	    }
68	    printItems(items);
69	  } else if (cmd === "search") {
70	    if (!args.length) fail("search requires a query");
71	    printItems(list.search(args.join(" ")));
72	  } else if (cmd === "tag" || cmd === "untag") {
73	    if (!args[1]) fail(`usage: todo ${cmd} <id> <tag>`);
74	    const id = Number(args[0]);
75	    if (cmd === "tag") list.addTag(id, args[1]);
76	    else list.removeTag(id, args[1]);
77	    list.save(file);
78	    console.log(`${cmd === "tag" ? "tagged" : "untagged"} ${id}: ${args[1]}`);
79	  } else if (cmd === "recur") {
80	    const freq = args[1];
81	    if (!["daily", "weekly", "monthly", "none"].includes(freq)) {
82	      fail("usage: todo recur <id> <daily|weekly|monthly|none>");
83	    }
84	    const item = list.items.find(i => i.id === Number(args[0]));
85	    if (!item) fail(`item ${args[0]} not found`);
86	    if (freq === "none") {
87	      delete item.repeat;
88	      delete item.repeatDay;
89	    } else {
90	      if (!item.due) fail(`item ${item.id} needs a due date to recur`);
91	      item.repeat = freq;
92	      item.repeatDay = new Date(item.due).getUTCDate();
93	    }
94	    list.save(file);
95	    console.log(`recurrence for ${args[0]}: ${freq}`);
96	  } else if (cmd === "export") {
97	    if (args.includes("--json")) console.log(JSON.stringify(list.items, null, 2));
98	    else if (args.includes("--csv")) console.log(toCsv(list.items));
99	    else fail("usage: todo export --json | --csv");
100	  } else {
101	    fail("usage: todo add <title> [--due DATE] [--priority P] | done <id> | list [--tag T] | search <q> | tag | untag | recur | export");
102	  }
103	} catch (e) {
104	  fail(e.message);
105	}
